// Jev: B-Roll Stills, ruled by Tee 2026-10-16. Lists the stock clips each b-roll
// segment would choose from, with the preview still of each, so Jev can look at
// the frames and score them against the narration. It decides which clips are
// in the running and nothing else: a Code node has no network access, so the
// stills are fetched by the HTTP node that follows. The branch runs in shadow
// and never changes which clip Build Movie picks.
//
// The candidate rule below is the rule in Build Movie's candidates(), and
// jev_broll_bodies.test.mjs keeps them in step by running both on the same
// Pexels response: mp4 files with a width, widest first, the first at or under
// 3840 wide (the smallest if none is), one link per video. The only difference
// is that each candidate also carries its video's still and id.
//
// A clip whose still is not on the Pexels image host is left out, so nothing
// from an unexpected host is ever fetched. Of the rest the first K_BROLL are
// kept, in Pexels order, and cand counts them from 1.
//
// Fails open: a missing node, a response with no videos (a failed Pexels call
// leaves an item with an error and no videos) or a malformed video gives that
// segment no candidates, and a segment with none adds nothing. Nothing here
// throws, because a Jev node must never stop the movie.
const K_BROLL = 4;
const STILL_HOST = 'https://images.pexels.com/';

function candidates(resp) {
  const vids = (resp && Array.isArray(resp.videos)) ? resp.videos : [];
  const out = [];
  for (const v of vids) {
    const files = (v.video_files || []).filter(f => (f.file_type || '').includes('mp4') && f.width);
    if (!files.length) continue;
    files.sort((a, b) => (b.width || 0) - (a.width || 0));
    const pick = files.find(f => f.width && f.width <= 3840) || files[files.length - 1];
    if (pick && pick.link) out.push({ link: pick.link, stillUrl: v.image, videoId: v.id });
  }
  return out;
}

const items = [];
try {
  const segs = $('Plan B-Roll Segments').all();
  const px = $('Pexels Search').all();
  for (let i = 0; i < segs.length; i++) {
    // Pexels Search runs once per segment in segment order, so item i answers segment i.
    let kept = [];
    try {
      kept = candidates(px[i] && px[i].json)
        .filter(c => typeof c.stillUrl === 'string' && c.stillUrl.startsWith(STILL_HOST))
        .slice(0, K_BROLL);
    } catch (e) { kept = []; }
    kept.forEach((c, n) => items.push({ json: { segIndex: i, cand: n + 1, link: c.link, stillUrl: c.stillUrl, videoId: c.videoId } }));
  }
} catch (e) { return []; }
return items;

// Jev: Thumb Stills. First node of the Jev side branch off Thumb: Find Still,
// ruled by Tee 2026-10-16, SHIPS IN SHADOW. It decides which photos Jev will be
// shown: the same photos Thumb: Pick Still considers, in the same order, at most
// three, each by the url Pick Still would draw (landscape, then large2x, then
// large). The next node fetches each photo as a file.
//
// Two urls travel on each item and they are not the same thing. url is exactly
// the url Pick Still would draw, and it is the key Pick Still uses to match a
// score to a photo, so it must not change. fetchUrl is what the HTTP fetch node
// must READ, and it is landscape, else large. TypeSafe rejects an image under
// 280 or over 1568 pixels on either side, and one rejected image fails the whole
// request with no partial answers. The large2x size is left out of fetchUrl on
// purpose: Pexels is said to document large2x as the 940x650 size at dpr 2, which
// would make it about 1880 pixels wide and over that limit. That Pexels figure is
// UNVERIFIED here, since no live Pexels response was read, so large2x is simply
// never fetched. A photo whose only url is large2x gets no item at all.
//
// k is the photo's 1-based place in the Pexels result, so a skipped photo leaves
// a gap in k rather than renumbering the rest. Jev: Thumb Body names its
// question p{k} from it and Thumb: Pick Still reads the score back the same way.
// Only a url on https://images.pexels.com/ is fetched, so this branch can never
// be made to call some other host. A Code node has no network access, so this
// node names urls and fetches nothing.
//
// Fail open: a Find Still that did not run, an error item with no photos or a
// photo with no usable url or fetchUrl gives fewer items or none. An empty return
// stops the branch, and Pick Still then keeps today's choice. This node never
// throws.
const K_THUMB = 3;
const HOST = 'https://images.pexels.com/';
const usable = (u) => typeof u === 'string' && u.startsWith(HOST);
const out = [];
try {
  const photos = $('Thumb: Find Still').first().json.photos;
  if (Array.isArray(photos)) {
    photos.slice(0, K_THUMB).forEach((photo, i) => {
      const src = photo && photo.src;
      const url = src ? (src.landscape || src.large2x || src.large) : null;
      if (!usable(url)) return;
      const fetchUrl = usable(src.landscape) ? src.landscape : (usable(src.large) ? src.large : null);
      if (!fetchUrl) return;
      out.push({ json: { k: i + 1, photoId: photo.id === undefined ? null : photo.id, url, fetchUrl } });
    });
  }
} catch (e) { return []; }
return out;

// Jev's check of the finished thumbnail, ruled by Tee 2026-10-16 and shipped in
// shadow. This is the body of Jev: Thumb Check Body, the Code node between the
// Extract From File that turned the composed frame into base64 (still_b64) and
// the TypeSafe call. It builds the request and sends nothing: Code nodes have
// no network access, and Jev: Check Thumb does the POST.
//
// It asks three things about the 1280x720 frame Thumb: Compose made, and the
// verdict node turns the answers into a note:
//   headline_present   is the headline on the image as text at all
//   headline_box       where that text sits. A Box question needs Jev 1.14
//                      (box.md). All three lanes send the pinned jev-1.14.0, ruled
//                      by Tee 2026-10-27 on a card, so the thresholds cannot move
//                      under the shadow numbers if TypeSafe moves an alias. On that
//                      day jev-latest and jev-preview both answered as jev-1.14.0,
//                      measured in harness execution 4737. The response's model
//                      field names the version that answered; the HTTP node's
//                      saved execution keeps it, and nothing downstream records it.
//   headline_readable  is every word of the headline easy to read at phone size.
//                      One condition, as noul.md asks for one per Noul. A headline
//                      touching the edge is the box rules' job in the verdict.
// A box question has no absent answer, so it is always paired with
// headline_present, and the verdict ignores the box when the headline is not found.
//
// The composed frame is sent once, in state, as images.md says for an image that
// several questions share (an image in a question's instructions is sent again for
// every question that holds it). The state is { thumb: "<thumb>", headline } and
// the three questions name `thumb` in backticks. None of them holds the reference
// string itself, so the image goes out once.
//
// Only a PNG or JPEG goes out, told apart by the base64 prefix. A request body
// is held to 20,000,000 characters of base64. An image that is missing, in
// another format or over that, or a row with no headline, returns [] and the
// branch stops. The Shim then reports exactly as it does today, because a check
// that cannot run must never make the thumbnail lane fail.
const MAX_B64 = 20000000;
let out = [];
try {
  const b64 = $input.first().json.still_b64;
  const headline = String($('Thumb: Pick Still').first().json.headline || '').trim();
  let format = null;
  if (typeof b64 === 'string' && b64.length > 0 && b64.length <= MAX_B64) {
    if (b64.startsWith('/9j/')) format = 'jpeg';
    else if (b64.startsWith('iVBORw0KGgo')) format = 'png';
  }
  if (format && headline) {
    out = [{ json: { body: {
      model: 'jev-1.14.0',
      state: { thumb: '<thumb>', headline },
      questions: {
        headline_present: {
          type: 'noul',
          instructions: 'Does `thumb` show the words in `headline` as text on the image?',
          criteria: {
            true: 'The words in headline appear on the image as text',
            false: 'The words in headline do not appear on the image as text',
          },
        },
        headline_box: {
          type: 'box',
          instructions: 'the headline text in `thumb`, the words in `headline`',
        },
        headline_readable: {
          type: 'noul',
          instructions: 'Is every word of the headline in `thumb` easy to read at phone size?',
          criteria: {
            true: 'Every word of the headline is easy to read at phone size',
            false: 'A word of the headline is hard to read at phone size',
          },
        },
      },
      assets: { '<thumb>': { type: 'image', format, data_base64: b64 } },
    } } }];
  }
} catch (e) {
  out = [];
}
return out;

// Jev: B-Roll Bodies, ruled by Tee 2026-10-16. Builds one TypeSafe request per
// b-roll segment that has at least one usable still, asking Jev how well each
// still works on screen while the narrator speaks that segment's sentence. It
// decides which stills go into a request and what is asked of them; the HTTP
// node after it sends the request and Build Movie reads the answers. The branch
// runs in shadow and never changes which clip Build Movie picks.
//
// Input is the Extract From File output, one item per still, in the order of
// the items from Jev: B-Roll Stills. The two are paired by position, so unequal
// lengths mean the pairing cannot be trusted and nothing is emitted. A Code node
// cannot read binary in separate mode, which is why the bytes arrive here as
// base64 in still_b64.
//
// A still is usable when its still_b64 is a non-empty string that starts like a
// JPEG or a PNG. TypeSafe accepts only those two, so a GIF, a WebP, an HTML
// error page fetched in place of an image and an error item are all skipped.
//
// A still whose width and height can be read from its first bytes and fall
// outside TypeSafe's limits is skipped too: it would be rejected, never resized,
// and one rejected image fails the whole request for the segment. A still whose
// size cannot be read is kept, so the check fails open to what this node did
// before it existed.
//
// The four score levels are told apart so that each one means one thing, and
// TypeSafe judges each on its own without its number or its neighbours. Level 0
// is a picture that cannot be used as b-roll at all (black or blank, blurred, a
// watermark, a logo or large text), and says nothing about the sentence. Level 1
// is a clean shot about something other than the sentence, level 2 a clean shot
// that fits the general topic, and level 3 a clean shot that clearly shows what
// the sentence describes. The score that comes back is a probability weighted
// mean of the level numbers, so it falls between levels. Level 2 is the first
// that says the picture fits the sentence.
//
// k counts the usable stills of a segment from 1, not the cand numbers from the
// stills node. Build Movie scores links[k-1] from the answer to s{segIndex}c{k},
// so the two must line up even when an earlier cand was skipped.
//
// One request body is capped at MAX_B64 base64 characters. Stills are in Pexels
// order, so when the cap bites the later ones, which Pexels ranked lowest, are
// dropped and the earlier ones stay.
//
// Fails open: any missing node, missing field or odd value gives that segment,
// or the whole node, no output, and the movie is built as it is today. Nothing
// here throws.
const MAX_B64 = 20000000;
const CRITERIA = [
  'Unusable as b-roll: mostly black or blank, blurred, or carrying a watermark, a logo or large text',
  'A clean, usable shot about something other than the sentence',
  'A clean shot that fits the general topic of the sentence',
  'A clean shot that clearly shows what the sentence describes'
];

// TypeSafe rejects an image under 280 or over 1568 pixels on either side, or
// outside 78,400 to 2,458,624 pixels in all, and the ends of each range are in
// (docs.typesafe.ai/images, Limits). Given the side limits the area limits
// follow, and both are kept so the numbers read as the page has them.
const MIN_SIDE = 280;
const MAX_SIDE = 1568;
const MIN_PIXELS = 78400;
const MAX_PIXELS = 2458624;
// Only the head of a still is decoded: a PNG keeps its size in its first 24
// bytes and a JPEG keeps it in the first frame header. 65,536 base64 characters
// are 49,152 bytes. Plain loops and arrays only, with no Buffer and no atob, so
// this runs whatever globals the Code node sandbox has.
const HEAD_CHARS = 65536;
const B64_VALUE = [];
'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'.split('').forEach((ch, n) => { B64_VALUE[ch.charCodeAt(0)] = n; });

// The first bytes of a still, or null when they are not base64.
const headBytes = (b64) => {
  const end = Math.min(b64.length, HEAD_CHARS);
  const bytes = [];
  let acc = 0;
  let bits = 0;
  for (let n = 0; n < end; n++) {
    const code = b64.charCodeAt(n);
    if (code === 61) break;                      // '=' ends the data
    const v = B64_VALUE[code];
    if (v === undefined) return null;
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((acc >> bits) & 255);
      acc &= (1 << bits) - 1;
    }
  }
  return bytes;
};
const u16 = (d, n) => d[n] * 256 + d[n + 1];
const u32 = (d, n) => d[n] * 16777216 + d[n + 1] * 65536 + d[n + 2] * 256 + d[n + 3];

// { w, h } from a PNG IHDR or from the first JPEG frame header (SOF), or null
// when the size cannot be read: the head is cut off, the structure is not what
// is expected, or a side is zero. It never throws.
const sizeOf = (b64, format) => {
  try {
    const d = headBytes(b64);
    if (!d) return null;
    let w;
    let h;
    if (format === 'png') {
      // 8 byte signature, then the first chunk, which is IHDR: its length, the
      // name, then width and height as 4 byte big endian numbers.
      if (d.length < 24 || d[12] !== 0x49 || d[13] !== 0x48 || d[14] !== 0x44 || d[15] !== 0x52) return null;
      w = u32(d, 16);
      h = u32(d, 20);
    } else {
      // SOI, then segments that each start FF and a marker code. A frame header
      // is 0xC0 to 0xCF except 0xC4 (Huffman tables), 0xC8 (reserved) and 0xCC
      // (arithmetic tables). Every other segment is stepped over by its length.
      let n = 2;
      for (;;) {
        if (d[n] !== 0xFF) return null;
        while (d[n + 1] === 0xFF) n++;           // fill bytes before a marker
        const m = d[n + 1];
        if (m === undefined || m === 0x00 || m === 0xD9 || m === 0xDA) return null;
        if (m >= 0xC0 && m <= 0xCF && m !== 0xC4 && m !== 0xC8 && m !== 0xCC) {
          if (d.length < n + 9) return null;
          h = u16(d, n + 5);
          w = u16(d, n + 7);
          break;
        }
        if (m === 0x01 || (m >= 0xD0 && m <= 0xD8)) { n += 2; continue; }   // no length
        const len = d.length < n + 4 ? 0 : u16(d, n + 2);
        if (len < 2) return null;
        n += 2 + len;
      }
    }
    return w > 0 && h > 0 ? { w, h } : null;
  } catch (e) { return null; }
};
const inLimits = (s) => s.w >= MIN_SIDE && s.w <= MAX_SIDE && s.h >= MIN_SIDE && s.h <= MAX_SIDE
  && s.w * s.h >= MIN_PIXELS && s.w * s.h <= MAX_PIXELS;

// TypeSafe reads the format from us, so it is taken from the first bytes: every
// JPEG base64 starts /9j/ and every PNG starts iVBORw0KGgo.
const formatOf = (b64) => {
  if (typeof b64 !== 'string') return null;
  if (b64.startsWith('/9j/')) return 'jpeg';
  if (b64.startsWith('iVBORw0KGgo')) return 'png';
  return null;
};

try {
  const stills = $('Jev: B-Roll Stills').all();
  const fetched = $input.all();
  // Unequal lengths: an item was dropped somewhere, so position no longer says
  // which still belongs to which segment.
  if (stills.length !== fetched.length) return [];
  const segs = $('Plan B-Roll Segments').all();

  // Usable stills grouped by segment, in segment order and then Pexels order.
  const bySeg = new Map();
  for (let n = 0; n < stills.length; n++) {
    const s = (stills[n] && stills[n].json) || {};
    const b64 = fetched[n] && fetched[n].json && fetched[n].json.still_b64;
    const format = formatOf(b64);
    if (!format || typeof s.link !== 'string' || !s.link) continue;
    if (!Number.isInteger(s.segIndex) || s.segIndex < 0) continue;
    // A size that is read and out of limits is skipped. One that cannot be read stays.
    const size = sizeOf(b64, format);
    if (size && !inLimits(size)) continue;
    if (!bySeg.has(s.segIndex)) bySeg.set(s.segIndex, []);
    bySeg.get(s.segIndex).push({ link: s.link, format, b64 });
  }

  const out = [];
  for (const [segIndex, usable] of bySeg) {
    // Plan B-Roll Segments sets segIndex to the item's own position, and Build
    // Movie reads it by that position, so the sentence is read the same way.
    const narration = segs[segIndex] && segs[segIndex].json && segs[segIndex].json.narration;
    if (typeof narration !== 'string' || !narration.trim()) continue;

    const links = [];
    const questions = {};
    const assets = {};
    let total = 0;
    for (const u of usable) {
      if (total + u.b64.length > MAX_B64) break;
      total += u.b64.length;
      links.push(u.link);
      const name = 's' + segIndex + 'c' + links.length;
      questions[name] = {
        type: 'score',
        instructions: 'How well does <' + name + '> work as b-roll on screen while a narrator says the sentence in `sentence`?',
        criteria: CRITERIA.slice()
      };
      assets['<' + name + '>'] = { type: 'image', format: u.format, data_base64: u.b64 };
    }
    if (!links.length) continue;

    out.push({ json: { segIndex, links, body: { model: 'jev-1.14.0', state: { sentence: narration }, questions, assets } } });
  }
  return out;
} catch (e) { return []; }

// Jev: Thumb Body. Builds the one TypeSafe request that asks Jev to score the
// candidate photos for a thumbnail, ruled by Tee 2026-10-16, SHIPS IN SHADOW.
// Its output item feeds Jev: Rank Stills, which posts json.body as it stands.
//
// The question asked of each photo is how well it works as the picture behind a
// thumbnail headline when a dark panel covers the left 60 percent of the frame,
// because that is what Thumb: Compose does. Scores run 0 to 3 and each level
// describes one situation on its own, because the model judges every level
// separately and never sees its number or its neighbours. A 0 is unusable: dark,
// cluttered, blurred, or carrying text or a watermark. A 1 is usable but about
// something other than the subject. A 2 fits the subject, but what matters sits
// on the left 60 percent of the frame, under the dark panel. A 3 fits the
// subject, and what matters sits in the right part of the frame, where it stays
// visible. A score comes back as a probability weighted mean of the level
// numbers, so it can fall between levels. Thumb: Pick Still reads the answers
// and reports the photo Jev would choose, and it uses that photo only once its
// own JEV_APPLY is true, so today's choice stands until then.
//
// Input is the Extract From File output, one item per fetched still with the
// image in json.still_b64, in the same order as Jev: Thumb Stills. The two are
// paired by position, so unequal lengths mean something dropped out between
// them and the pairing cannot be trusted. Only PNG and JPEG are accepted, found
// by the base64 prefix, and anything else is skipped. Question p{k} refers to
// its photo by the placeholder <p{k}>, and every asset must be referenced, so
// each asset key appears in its own question.
//
// Size check. TypeSafe rejects an image under 280 or over 1568 pixels on either
// side, and one rejected image fails the whole request with no partial answers.
// The total pixel range in its docs, 78,400 to 2,458,624, is the area of a 280 by
// 280 and a 1568 by 1568 square, so the side check already covers it. The size is
// read from the first 65,536 base64 characters only, by hand, with no Buffer and
// no atob, so it works whatever globals the Code sandbox has. A PNG gives it in
// IHDR and a JPEG in the first SOF marker. A still whose size is read and is out
// of limits is skipped like any other unusable still. A still whose size cannot
// be read, because the header is odd or the SOF sits past that window, is kept,
// so the check fails open to what this node did before it existed.
//
// urls[k-1] is the url the question p{k} was about, null where no question was
// asked, so Pick Still can match a score to a photo by url.
//
// Fail open: a missing node, a length mismatch, no readable image or no subject
// or headline returns [], the branch stops, and the thumbnail is chosen as it is
// today. One request body is held under 20,000,000 characters of base64, and
// the later photos, the lower ranked in Pexels order, are dropped beyond that.
// This node never throws.
const BODY_CAP = 20000000;
const CRITERIA = [
  'Unusable: dark, cluttered, blurred, or carrying text or a watermark',
  'Usable, but about something other than the subject',
  'Fits the subject, but what matters sits on the left 60 percent of the frame, under the dark panel',
  'Fits the subject, and what matters sits in the right part of the frame, where it stays visible',
];
const formatOf = (b64) => (b64.startsWith('/9j/') ? 'jpeg' : (b64.startsWith('iVBORw0KGgo') ? 'png' : null));
const MIN_SIDE = 280;
const MAX_SIDE = 1568;
const HEAD_CHARS = 65536;
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
// The leading bytes of a base64 string as plain numbers. It stops at the first
// character that is not in the standard alphabet, which is the '=' padding.
const headBytes = (b64) => {
  const s = b64.slice(0, HEAD_CHARS);
  const out = [];
  let acc = 0;
  let bits = 0;
  for (let i = 0; i < s.length; i++) {
    const v = B64.indexOf(s.charAt(i));
    if (v < 0) break;
    acc = ((acc << 6) | v) & 0xffff;
    bits += 6;
    if (bits >= 8) { bits -= 8; out.push((acc >> bits) & 255); }
  }
  return out;
};
const be16 = (b, i) => b[i] * 256 + b[i + 1];
const be32 = (b, i) => b[i] * 16777216 + b[i + 1] * 65536 + b[i + 2] * 256 + b[i + 3];
// PNG: the signature, then IHDR as the first chunk, 13 bytes long, width and
// height as 32 bit big endian numbers.
const pngSize = (b) => {
  if (b.length < 24 || be32(b, 8) !== 13) return null;
  if (b[12] !== 0x49 || b[13] !== 0x48 || b[14] !== 0x44 || b[15] !== 0x52) return null;
  const w = be32(b, 16);
  const h = be32(b, 20);
  return w > 0 && h > 0 ? { w, h } : null;
};
// JPEG: walk the segments by their length, so a thumbnail embedded in an APP
// segment is skipped whole, and read the first SOF marker (0xC0 to 0xCF except
// 0xC4, 0xC8 and 0xCC). Reaching the scan or the end first, or a byte that is
// not a marker, means the size cannot be read. A height of 0 is defined later by
// a DNL segment, so that is unreadable too.
const jpegSize = (b) => {
  let i = 2;
  while (i + 3 < b.length) {
    if (b[i] !== 0xff) return null;
    const m = b[i + 1];
    if (m === 0xff) { i += 1; continue; }
    if (m === 0x00 || m === 0xd9 || m === 0xda) return null;
    if (m === 0x01 || (m >= 0xd0 && m <= 0xd8)) { i += 2; continue; }
    const len = be16(b, i + 2);
    if (m >= 0xc0 && m <= 0xcf && m !== 0xc4 && m !== 0xc8 && m !== 0xcc) {
      if (len < 8 || i + 8 >= b.length) return null;
      const h = be16(b, i + 5);
      const w = be16(b, i + 7);
      return w > 0 && h > 0 ? { w, h } : null;
    }
    if (len < 2) return null;
    i += 2 + len;
  }
  return null;
};
const sizeOf = (b64, format) => {
  const b = headBytes(b64);
  return format === 'png' ? pngSize(b) : jpegSize(b);
};
const outOfLimits = (d) => d.w < MIN_SIDE || d.h < MIN_SIDE || d.w > MAX_SIDE || d.h > MAX_SIDE;
try {
  const files = $input.all();
  const stills = $('Jev: Thumb Stills').all();
  if (!files.length || files.length !== stills.length) return [];
  const plan = $('Thumb: Plan').first().json;
  const subject = String(plan.queryRaw || '').trim();
  const headline = String(plan.headline || '').trim();
  if (!subject || !headline) return [];
  const questions = {};
  const assets = {};
  const urls = [];
  let size = 0;
  for (let i = 0; i < files.length; i++) {
    const meta = stills[i] && stills[i].json;
    const b64 = files[i] && files[i].json && files[i].json.still_b64;
    const k = meta && meta.k;
    if (!Number.isInteger(k) || k < 1 || typeof meta.url !== 'string') continue;
    if (typeof b64 !== 'string' || !b64) continue;
    const format = formatOf(b64);
    if (!format) continue;
    const dim = sizeOf(b64, format);
    if (dim && outOfLimits(dim)) continue;
    if (size + b64.length > BODY_CAP) break;
    size += b64.length;
    const ref = 'p' + k;
    questions[ref] = {
      type: 'score',
      instructions: 'How well does <' + ref + '> work as the photograph behind a YouTube thumbnail about `subject`, where a dark panel covers its left 60 percent and `headline` sits on that panel?',
      criteria: CRITERIA.slice(),
    };
    assets['<' + ref + '>'] = { type: 'image', format, data_base64: b64 };
    while (urls.length < k) urls.push(null);
    urls[k - 1] = meta.url;
  }
  if (!Object.keys(questions).length) return [];
  return [{ json: { urls, body: { model: 'jev-1.14.0', state: { subject, headline }, questions, assets } } }];
} catch (e) { return []; }

// Jev's check of the finished thumbnail, ruled by Tee 2026-10-16 and shipped in
// shadow. This is the body of Jev: Thumb Verdict, the Code node after the
// TypeSafe call that Jev: Thumb Check Body built. It turns Jev's three answers
// into one note. The Shim records it, and adds it to thumb_warning only when
// its JEV_APPLY is true. No note names Jev, because the Shim's "Jev: " prefix
// does that once for the whole line. Every rule is
// computed here from the numbers, none is left to Jev's own wording, so the
// same answers always give the same note.
//
// It also returns forHeadline, the headline the request was built for, read from
// Jev: Thumb Check Body's state. One Row at a Time is a Split In Batches loop, so
// when a later row's Jev branch stops early the Shim's lookup of this node may
// hand it an earlier row's verdict (unverified n8n behaviour, guarded either
// way). The Shim uses forHeadline to tell: it takes the verdict only when
// forHeadline equals the headline of the row it is shaping.
//
// The rules, in order:
//   headline_present below 0.5   "the headline text was not found on the
//                                thumbnail". The box answer is not looked at,
//                                not even to check its shape: TypeSafe's Box
//                                always returns four edges and has no not
//                                found answer, so with the headline absent the
//                                box is a guess, and its docs say to ignore it
//                                when the Noul is low. A reversed or zero area
//                                box beside an absent headline therefore still
//                                gives this note. headline_readable is not read
//                                either.
//   otherwise, box right edge above TEXT_RIGHT (0.603125)
//                                the headline runs off the dark panel. The
//                                threshold is the designed right edge of the
//                                text, not the scrim edge: see TEXT_RIGHT.
//   box bottom above 0.95, or top or left below 0.02
//                                the headline touches the edge of the frame.
//   headline_readable below 0.5  the headline is hard to read at phone size.
// Several notes join with "; ", in that order.
//
// jevThumbChecked says the answers were usable. A response that is not from a
// jev- model, or has headline_present missing, of the wrong type, not finite
// or out of range, is ignored whole: checked false, no note, no box. The same
// holds for headline_readable and the box answer, but only once the headline
// is found (present 0.5 or more), because only then are they read. A silent
// note is then not mistaken for a clean frame. A box must also have top above
// bottom and left above right, or it is out of range too. A value of exactly 0
// or exactly 1 is in range, for an answer and for a box edge alike.
//
// forHeadline is read apart from all of that, so a failure to read it never
// changes the verdict: null when Jev: Thumb Check Body did not run or holds no
// headline string, the headline otherwise. It rides on every verdict, checked
// or not.
//
// TEXT_RIGHT is the designed right edge of the headline text, as a fraction of
// the 1280 px frame. Thumb: Compose draws the headline at x 72 and Thumb: Pick
// Still wraps it to a 700 px budget (floor(700 / (size * 0.52)) characters), so a
// full line ends near x 772. The dark panel (scrim) ends at x 760, a little
// inside that, so the scrim edge is not the line between "inside the design" and
// "ran off": 760 / 1280 would flag a full line that is laid out as designed.
// This is a STARTING VALUE to tune from shadow data, not a measured one.
// jev_thumb_check.test.mjs reads the export and fails when the compositor's
// position, width or budget moves without this line.
const TEXT_RIGHT = (72 + 700) / 1280;
const EDGE_LOW = 0.02;
const EDGE_BOTTOM = 0.95;
const HALF = 0.5;

const unit = (v) => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1;
const noulOf = (a) => (a && a.type === 'noul' && unit(a.noul) ? a.noul : null);
const boxOf = (a) => {
  const b = a && a.type === 'box' ? a.box : null;
  if (!b || ![b.top, b.bottom, b.left, b.right].every(unit)) return null;
  if (!(b.top < b.bottom && b.left < b.right)) return null;
  return { top: b.top, bottom: b.bottom, left: b.left, right: b.right };
};

let verdict = { jevThumbNote: null, jevThumbChecked: false, jevHeadlineBox: null };
try {
  const r = $input.first().json;
  const answers = r && typeof r.model === 'string' && r.model.startsWith('jev-') ? r.answers : null;
  if (answers && typeof answers === 'object') {
    const present = noulOf(answers.headline_present);
    const readable = noulOf(answers.headline_readable);
    if (present !== null) {
      if (present < HALF) {
        // Neither the box nor readable is read on this branch.
        verdict = { jevThumbNote: 'the headline text was not found on the thumbnail', jevThumbChecked: true, jevHeadlineBox: null };
      } else {
        const box = boxOf(answers.headline_box);
        if (box !== null && readable !== null) {
          const notes = [];
          if (box.right > TEXT_RIGHT) notes.push('the headline runs off the dark panel onto the photograph');
          if (box.bottom > EDGE_BOTTOM || box.top < EDGE_LOW || box.left < EDGE_LOW) notes.push('the headline touches the edge of the frame');
          if (readable < HALF) notes.push('the headline is hard to read at phone size');
          verdict = {
            jevThumbNote: notes.length ? notes.join('; ') : null,
            jevThumbChecked: true,
            jevHeadlineBox: box,
          };
        }
      }
    }
  }
} catch (e) {
  verdict = { jevThumbNote: null, jevThumbChecked: false, jevHeadlineBox: null };
}

// The headline this request was built for, so the Shim can tell a stale verdict
// from this row's own. Read apart from the verdict: unreadable is null.
let forHeadline = null;
try {
  const h = $('Jev: Thumb Check Body').first().json.body.state.headline;
  if (typeof h === 'string') forHeadline = h;
} catch (e) {
  forHeadline = null;
}
return [{ json: { ...verdict, forHeadline } }];

